-- ============================================================
-- import_grn.sql
-- GRN header records and line items — Gingersnaps WMS
-- Generated : 2026-10-24
-- Revised   : 2026-10-31 — po_number mismatch fix applied
-- Source    : grn.csv  (9277 item rows, 1693 unique GRNs)
-- Safe to re-run  (INSERT IGNORE + unique-key idempotency guard)
--
-- PO_NUMBER FIX (2026-10-31):
--   grn.csv exports PO codes without a version suffix in some cases
--   (e.g. GBL1757_WFR) while po.csv / purchase_orders stores the
--   versioned form (GBL1757_WFR-1).  29 distinct PO codes were
--   corrected to their exact po.csv values (61 WHERE clauses updated).
--   Coverage after fix: 755 of 974 referenced PO codes will link.
--   219 codes remain unresolvable (POs absent from po.csv export;
--   those GRN rows are silently skipped by INSERT IGNORE).
--
-- COLUMN NOTE: grn_items uses `qty_received` for received quantity
--   (NOT `qty`).  If the live table still has the Sprint-2 column
--   name `qty_received`, rename it first:
--     ALTER TABLE grn_items RENAME COLUMN qty_received TO qty_received;
--
-- HOW TO APPLY
--   cPanel phpMyAdmin → select gingersnaps_db →
--   Import tab → choose this file → Go
-- ============================================================
SET FOREIGN_KEY_CHECKS=0;
SET NAMES utf8mb4;

-- ============================================================
-- Step 0: Idempotency guard for grn_items
-- Unique index on (grn_id, sku_code) ensures INSERT IGNORE skips
-- duplicate rows on every subsequent run.
-- ============================================================
ALTER TABLE `grn_items`
  ADD UNIQUE INDEX IF NOT EXISTS `uq_grni_grn_sku` (`grn_id`, `sku_code`(100));

START TRANSACTION;

-- ============================================================
-- Step 1: GRN header records (1693 rows)
-- INSERT ... SELECT FROM purchase_orders guarantees po_id is
-- never NULL (rows with missing POs are silently skipped).
-- ============================================================
INSERT IGNORE INTO `grn`
  (`grn_code`,`grn_date`,`po_id`,`subcon_id`,`invoice_no`,`invoice_date`,
   `gate_entry`,`total_qty_received`,`total_qty_rejected`,`status`,
   `created_by`,`created_at`,`updated_at`)
SELECT
  'G1972','2025-11-11',
  po.po_id,
  (SELECT subcon_id FROM `subcons` WHERE subcon_name='YKP' LIMIT 1),
  'TS/DR#8459/11-11-25/ROBINMAR','2025-11-10',
  NULL,4,0,
  'COMPLETED',
  COALESCE((SELECT user_id FROM `users` WHERE email='cs.top.gingersnaps@gmail.com' LIMIT 1), 1),
  '2025-11-11 10:52:23','2026-09-15 07:03:20'
FROM `purchase_orders` po
WHERE po.po_number='PDR0975_WHL'
LIMIT 1;

